import{_ as a}from"./chunks/img.Dck1PxLc.js";import{_ as e,C as o,c as i,o as t,j as r,G as n,a0 as s,a as l}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Acerca de la Academia de Petanca","description":"","frontmatter":{},"headers":[],"relativePath":"es/about.md","filePath":"es/about.md"}');const d=e({name:"es/about.md"},[["render",function(e,c,d,u,m,p){const g=o("AdBanner"),h=o("AdInArticle");return t(),i("div",null,[c[0]||(c[0]=r("h1",{id:"acerca-de-la-academia-de-petanca",tabindex:"-1"},[l("Acerca de la Academia de Petanca "),r("a",{class:"header-anchor",href:"#acerca-de-la-academia-de-petanca","aria-label":'Permalink to "Acerca de la Academia de Petanca"'},"​")],-1)),n(g),c[1]||(c[1]=s('<h2 id="una-pasion-por-la-petanca" tabindex="-1">Una pasión por la petanca <a class="header-anchor" href="#una-pasion-por-la-petanca" aria-label="Permalink to &quot;Una pasión por la petanca&quot;">​</a></h2><p>Bienvenidos a la Academia de Petanca, donde una profunda pasión por la petanca me ha impulsado durante más de 45 años. Mi trayectoria en este deporte ha estado marcada por la dedicación, la habilidad y el entusiasmo constante.</p><p>La petanca no es solo un juego; es una forma de conectar, crear estrategias y disfrutar del aire libre, y he tenido la suerte de experimentar sus múltiples facetas durante casi medio siglo. Ya sea por la precisión en la colocación de una bola o por la camaradería en el campo, mi compromiso con la petanca sigue tan firme como siempre.</p><p><img src="'+a+'" alt="Patrik Wiik with friends"></p><p>Compartir esta pasión con amigos es lo que hace de la petanca algo tan especial. Las incontables horas que pasamos en el campo, llenas de risas, competencia amistosa e historias compartidas, forjan lazos que duran toda la vida.</p><hr><h2 id="mi-mision" tabindex="-1">Mi misión <a class="header-anchor" href="#mi-mision" aria-label="Permalink to &quot;Mi misión&quot;">​</a></h2><p>La misión de Pétanque Academy es ayudar a los jugadores de élite a liberar todo su potencial abordando el juego mental, el aspecto a menudo pasado por alto que separa a los buenos jugadores de los excelentes.</p><p>A través de este sitio comparto: <strong>Marcos de juego mental</strong> desarrollados a partir de décadas de experiencia</p><ul><li><strong>Herramientas y plantillas prácticas</strong> para el establecimiento de objetivos y la formación.</li><li><strong>Metodologías de taller</strong> para construir seguridad psicológica <strong>Enfoques basados en evidencia</strong> para el desempeño bajo presión</li></ul><p>No se trata de entrenamiento técnico: se trata de crear la base mental que permita que tus habilidades técnicas brillen cuando más importa.</p><hr><h2 id="¿por-que-cree-este-sitio" tabindex="-1">¿Por qué creé este sitio? <a class="header-anchor" href="#¿por-que-cree-este-sitio" aria-label="Permalink to &quot;¿Por qué creé este sitio?&quot;">​</a></h2><p>Después de más de 45 años jugando a la petanca, he visto a innumerables jugadores talentosos luchar no con la técnica, sino con:</p><ul><li><strong>Crítico interno</strong> que destruye la confianza después de los errores.</li><li><strong>Presión</strong> que les hace jugar de forma diferente en la competición</li><li><strong>Falta de estructura</strong> en el entrenamiento mental</li><li><strong>Aislamiento</strong> en su camino hacia el desarrollo</li></ul><p>Este sitio existe para cambiar eso. Todo el contenido está diseñado para ser práctico de inmediato: plantillas que puedes copiar, marcos que puedes aplicar hoy mismo y herramientas que funcionan en la competencia real.</p><hr>',17)),n(h),c[2]||(c[2]=s('<h2 id="contactanos" tabindex="-1">Contáctanos <a class="header-anchor" href="#contactanos" aria-label="Permalink to &quot;Contáctanos&quot;">​</a></h2><p>¡Me encantaría saber de ti! Si tienes preguntas, quieres compartir tu experiencia o te interesan los talleres y la capacitación, no dudes en contactarnos.</p><h3 id="informacion-del-contacto" tabindex="-1">Información del contacto <a class="header-anchor" href="#informacion-del-contacto" aria-label="Permalink to &quot;Información del contacto&quot;">​</a></h3><p><strong>Correo electrónico:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Facebook:</strong> <a href="https://www.facebook.com/patrik.wiik" target="_blank" rel="noreferrer">facebook.com/patrik.wiik</a></p><hr><h2 id="ayudame-a-mejorar-este-sitio" tabindex="-1">Ayúdame a mejorar este sitio <a class="header-anchor" href="#ayudame-a-mejorar-este-sitio" aria-label="Permalink to &quot;Ayúdame a mejorar este sitio&quot;">​</a></h2><p>¡Tus comentarios son invaluables! Este sitio evoluciona constantemente según las necesidades reales de los jugadores de élite.</p><h3 id="me-encantaria-saber-de-usted-acerca-de" tabindex="-1">Me encantaría saber de usted acerca de: <a class="header-anchor" href="#me-encantaria-saber-de-usted-acerca-de" aria-label="Permalink to &quot;Me encantaría saber de usted acerca de:&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">¿Qué te ayudaría más?</p><ul><li><p><strong>¿Qué contenido te gustaría ver más?</strong></p><ul><li>¿Más técnicas de juego mental?</li><li>¿Plantillas más prácticas?</li><li>¿Estudios de caso de jugadores de élite?</li></ul></li><li><p><strong>¿Qué falta en el sitio?</strong></p><ul><li>¿Temas no cubiertos?</li><li>¿Herramientas que desearías que existieran?</li><li>¿Recursos que no puedes encontrar?</li></ul></li><li><p>¿Qué está funcionando bien? -¿Qué páginas te han resultado más útiles? -¿Qué herramientas has utilizado realmente?</p><ul><li>¿Qué fue lo que marcó la mayor diferencia para usted?</li></ul></li><li><p><strong>¿Cómo puedo hacerlo mejor?</strong></p><ul><li>¿Mejoras en la navegación? -¿Organización de contenidos?</li><li>¿Más ejemplos?</li><li>¿Diferentes formatos?</li></ul></li></ul></div><h3 id="enviame-tus-comentarios" tabindex="-1">Envíame tus comentarios <a class="header-anchor" href="#enviame-tus-comentarios" aria-label="Permalink to &quot;Envíame tus comentarios&quot;">​</a></h3><p><strong>Envía tus pensamientos por correo electrónico a:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Sugerencias de líneas de asunto:</strong></p><ul><li>&quot;Comentarios del sitio: [Su tema]&quot;</li><li>&quot;Solicitud de contenido: [Lo que necesitas]&quot;</li><li>&quot;Historia de éxito: [Cómo ayudó]&quot;</li><li>&quot;Sugerencia: [Tu idea]&quot;</li></ul><p><strong>Qué incluir:</strong></p><ul><li>Tu nivel/experiencia actual</li><li>En qué estás trabajando</li><li>Comentarios o solicitudes específicas</li><li>¿Alguna historia de éxito utilizando el contenido?</li></ul><hr><h2 id="lo-que-dicen-los-demas" tabindex="-1">Lo que dicen los demás <a class="header-anchor" href="#lo-que-dicen-los-demas" aria-label="Permalink to &quot;Lo que dicen los demás&quot;">​</a></h2><details class="details custom-block"><summary>Comentarios de jugadores de élite</summary><p><em>&quot;El contenido del juego mental ha cambiado por completo mi forma de afrontar la competición. Solo por el marco del Entrenador Interno valió la pena encontrar este sitio.&quot;</em> — Campeón regional, Francia</p><p><em>&quot;Por fin, alguien que entiende que la técnica no es el problema. La metodología del taller le dio a nuestro club una forma completamente nueva de entrenar.&quot;</em> — Jugador de la selección nacional de Suecia</p><p><em>&quot;La plantilla de objetivos y la plantilla de diario son justo lo que necesitaba. Sencillas, prácticas y realmente útiles.&quot;</em> — Jugador de torneos, España</p></details><hr><h2 id="acerca-del-contenido" tabindex="-1">Acerca del contenido <a class="header-anchor" href="#acerca-del-contenido" aria-label="Permalink to &quot;Acerca del contenido&quot;">​</a></h2><p>Todo el contenido de este sitio es:</p><ul><li><strong>Gratis y accesible</strong> - Sin muros de pago, sin contenido oculto <strong>Práctico y viable</strong> - Plantillas que puedes usar hoy mismo</li><li><strong>Basado en evidencia</strong> - Construido sobre investigación psicológica y más de 45 años de experiencia</li><li><strong>Actualizado continuamente</strong> - Se agregó nuevo contenido según sus comentarios.</li></ul><hr><h2 id="privacidad-y-cookies" tabindex="-1">Privacidad y cookies <a class="header-anchor" href="#privacidad-y-cookies" aria-label="Permalink to &quot;Privacidad y cookies&quot;">​</a></h2><p>Este sitio utiliza Google AdSense para su funcionamiento. Al usar este sitio, acepta el uso de cookies de Google para la personalización y el análisis de anuncios.</p><p><strong>Respetamos su privacidad:</strong></p><ul><li>No se recopilan datos personales más allá de los análisis estándar.</li><li>Sin listas de correo electrónico ni spam</li><li>La información de contacto solo se utiliza para responder a sus mensajes.</li></ul><hr><h2 id="conectar-y-compartir" tabindex="-1">Conectar y compartir <a class="header-anchor" href="#conectar-y-compartir" aria-label="Permalink to &quot;Conectar y compartir&quot;">​</a></h2><p>Si encuentra este contenido valioso:</p><ul><li><strong>Compártelo</strong> con tus compañeros de entrenamiento</li><li><strong>Recomiéndalo</strong> a tu club</li><li><strong>Enlace al mismo</strong> desde tus propios recursos</li><li><strong>Dar retroalimentación</strong> para ayudar a mejorar</li></ul><p>Juntos, podemos elevar el juego mental de la petanca en todo el mundo.</p><hr>',34)),n(g),c[3]||(c[3]=r("p",null,[r("strong",null,"¡Gracias por ser parte de la Academia de Petanca!")],-1)),c[4]||(c[4]=r("p",null,[r("em",null,"—Patrik Wiik")],-1))])}]]);export{c as __pageData,d as default};
